INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('EV/EBITDA', 'EV/EBITDA', '평가 배수', '기업가치가 이자, 세금, 감가상각비 차감 전 이익의 몇 배인지 나타내는 지표입니다.', '기업가치(EV) ÷ EBITDA', '동종 발전사와 비교하되 전력가격, 원전 가동률, 정비비를 반영한 정상 EBITDA 기준을 사용해야 합니다.', 'ev_to_ebitda', 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('FCF_YIELD', 'FCF Yield', '평가 배수', '주식의 시장가치 대비 잉여현금흐름 비율입니다. 현재 가격에서 얻는 현금 수익력을 나타냅니다.', '잉여현금흐름(FCF) ÷ 시가총액 × 100', '높을수록 가격 대비 현금창출력이 크지만 대규모 정비와 투자 시점에 따라 연간 수치가 크게 달라질 수 있습니다.', 'fcf_yield_market_cap', 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('CONTRACT_VIS', '계약 가시성', '가치 동인', '미래 발전량과 매출 중 장기 계약으로 가격과 물량이 정해진 범위를 뜻합니다.', NULL, '계약 기간, 물량, 가격 조정 조건과 추가 설비투자 의무를 함께 확인해야 합니다.', NULL, 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('EV/SALES', 'EV/Sales', '평가 배수', '기업가치가 연간 매출의 몇 배인지 나타내는 지표입니다.', '기업가치(EV) ÷ 매출', '제품 믹스와 수익성이 다른 기업끼리는 같은 배수라도 의미가 다르므로 마진과 함께 봐야 합니다.', 'ev_to_sales', 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('EBITDA_MARGIN', 'EBITDA Margin', '운영 지표', '매출 중 EBITDA로 남는 비율입니다.', 'EBITDA ÷ 매출 × 100', '조정 항목이 많을 때는 GAAP 영업이익과 주식보상비용, 구조조정비를 함께 확인해야 합니다.', 'ebitda_margin', 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('FCF_CONVERSION', 'FCF 전환율', '운영 지표', 'EBITDA 가운데 잉여현금흐름으로 전환된 비율입니다.', '잉여현금흐름(FCF) ÷ EBITDA × 100', '재고 축적, 고객 선급금과 설비투자 시점이 단기 전환율을 크게 움직일 수 있습니다.', 'fcf_conversion', 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('FORWARD_PE', 'Forward P/E', '평가 배수', '현재 주가가 향후 12개월 예상 주당순이익의 몇 배인지 나타냅니다.', '현재 주가 ÷ 향후 12개월 예상 EPS', '반도체 업황, 환율과 예상 이익의 기준 시점이 달라지면 배수도 빠르게 바뀔 수 있습니다.', 'forward_pe', 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('GROSS_MARGIN', 'Gross Margin', '운영 지표', '매출에서 매출원가를 차감한 뒤 남는 비율입니다.', '매출총이익 ÷ 매출 × 100', '공정 믹스, 가동률, 환율과 해외 팹 초기 비용이 단기 마진에 영향을 줍니다.', 'gross_margin', 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
INSERT INTO `metric_definitions` (`code`, `label`, `category`, `definition`, `formula_display`, `interpretation`, `calculation_key`, `definition_version`) VALUES ('CAPEX_INTENSITY', 'CAPEX / 매출', '운영 지표', '매출 대비 설비투자 규모를 나타내는 비율입니다.', '설비투자(CAPEX) ÷ 매출 × 100', '투자와 매출 발생 시점이 다르므로 단일 연도보다 여러 해의 추세와 신규 팹 가동 계획을 함께 봐야 합니다.', 'capex_intensity', 1) ON CONFLICT (`code`) DO UPDATE SET `label` = excluded.`label`, `category` = excluded.`category`, `definition` = excluded.`definition`, `formula_display` = excluded.`formula_display`, `interpretation` = excluded.`interpretation`, `calculation_key` = excluded.`calculation_key`, `definition_version` = excluded.`definition_version`;
