INSERT INTO `company_research_profiles` (`company_ticker`, `business_model`, `revenue_model`, `customer_structure`, `cost_structure`, `capital_intensity`, `as_of_date`, `source_ids`, `content_version`) VALUES ('CEG', '발전 자산에서 생산한 전력·용량·환경가치를 도매시장과 장기계약으로 판매하고, 별도의 소매 플랫폼을 통해 기업·공공·가정 고객에게 전력과 에너지 솔루션을 공급합니다. 발전과 고객 부하를 함께 보유해 양쪽의 가격 위험을 통합 관리합니다.', '전력 판매, 용량·보조서비스, 소매 전력 공급과 에너지 서비스가 주요 수익원입니다. 장기계약과 헤지로 현금흐름을 일부 고정하지만 발전량과 지역별 전력·가스 가격에도 노출됩니다.', '유틸리티·지자체·협동조합과 상업·산업·공공·주거 고객을 상대합니다. Calpine 합병 후 약 250만 고객 계정과 Fortune 100의 약 4분의 3을 고객으로 둔다고 회사가 공시했습니다.', '연료와 구입전력, 원전 계획예방정비·핵연료, 가스발전 정비, 담보·헤지 비용, 인건비와 폐로 의무가 핵심 비용입니다. 발전소 가동률과 정비 일정이 단기 수익성을 크게 움직입니다.', '매우 높습니다. 원전 수명연장·출력증강, 정기 정비, 가스발전 유지보수와 신규 발전·저장 자산에 장기간 자본을 투입해야 합니다.', '2026-02-24', '["CEG_2025_10K"]', 1) ON CONFLICT (`company_ticker`) DO UPDATE SET `business_model` = excluded.`business_model`, `revenue_model` = excluded.`revenue_model`, `customer_structure` = excluded.`customer_structure`, `cost_structure` = excluded.`cost_structure`, `capital_intensity` = excluded.`capital_intensity`, `as_of_date` = excluded.`as_of_date`, `source_ids` = excluded.`source_ids`, `content_version` = excluded.`content_version`;
INSERT INTO `company_research_profiles` (`company_ticker`, `business_model`, `revenue_model`, `customer_structure`, `cost_structure`, `capital_intensity`, `as_of_date`, `source_ids`, `content_version`) VALUES ('COHR', '소재 성장부터 광소자·트랜시버·레이저 시스템까지 수직 통합해 고성능 광학·포토닉스 부품을 제조하고 OEM과 최종 수요처에 판매합니다. 고객 시스템의 핵심 부품을 공동 설계·인증한 뒤 양산 공급하는 구조입니다.', '데이터센터·통신용 광트랜시버와 부품, 반도체·디스플레이 장비용 레이저·광학계, 산업·계측용 제품 판매가 대부분의 매출을 만듭니다. 제품 믹스와 고객 주문·인증 주기가 마진에 영향을 줍니다.', '전 세계 OEM과 최종 고객을 상대하며 기술영업이 설계·시험·인증을 지원합니다. FY2025에는 각각 매출 10%를 넘는 고객이 두 곳이어서 AI 네트워킹 고객 집중도를 함께 봐야 합니다.', '화합물반도체와 특수소재 제조, IC·DSP·광학 부품 조달, 높은 R&D, 제조 수율과 글로벌 생산설비 고정비가 핵심입니다. 일부 레이저 소재·부품은 단일 또는 제한 공급원에 의존합니다.', '중상 수준입니다. InP·GaAs 등 소재와 소자 생산능력, 데이터센터 트랜시버 양산, 레이저 제조설비에 선행 투자가 필요하며 수요 조정기에는 가동률 부담이 발생합니다.', '2025-08-15', '["COHR_2025_10K"]', 1) ON CONFLICT (`company_ticker`) DO UPDATE SET `business_model` = excluded.`business_model`, `revenue_model` = excluded.`revenue_model`, `customer_structure` = excluded.`customer_structure`, `cost_structure` = excluded.`cost_structure`, `capital_intensity` = excluded.`capital_intensity`, `as_of_date` = excluded.`as_of_date`, `source_ids` = excluded.`source_ids`, `content_version` = excluded.`content_version`;
INSERT INTO `company_research_profiles` (`company_ticker`, `business_model`, `revenue_model`, `customer_structure`, `cost_structure`, `capital_intensity`, `as_of_date`, `source_ids`, `content_version`) VALUES ('TSM', '고객이 설계한 반도체를 위탁 생산하는 전용 파운드리입니다. 자체 브랜드 칩으로 고객과 경쟁하지 않고 공정기술·대규모 생산능력·설계 생태계를 제공해 고객의 설계를 양산 제품으로 전환합니다.', '공정 노드별 웨이퍼 제조가 중심이며 설계지원·마스크, 첨단 패키징과 테스트 서비스가 결합됩니다. 선단공정과 HPC 비중, 웨이퍼 가격, 가동률과 수율이 매출과 마진을 결정합니다.', '팹리스, 시스템 기업과 IDM을 포함한 글로벌 반도체 고객을 직접 지원합니다. 2025년 상위 10개 고객이 매출의 78%, 최대 고객이 19%, 두 번째 고객이 17%를 차지했습니다.', '팹 감가상각, 장비·소재·전력·용수, 인력과 선행 R&D가 주요 비용입니다. 첨단 노드와 해외 신규 팹의 초기 가동비가 단기 총마진을 낮출 수 있습니다.', '매우 높습니다. 2·3나노, 특수공정과 첨단 패키징 증설에 대규모 선행투자가 필요하며 회사는 2026년 CAPEX를 520억~560억 달러로 예상했습니다.', '2026-04-16', '["TSM_2025_20F"]', 1) ON CONFLICT (`company_ticker`) DO UPDATE SET `business_model` = excluded.`business_model`, `revenue_model` = excluded.`revenue_model`, `customer_structure` = excluded.`customer_structure`, `cost_structure` = excluded.`cost_structure`, `capital_intensity` = excluded.`capital_intensity`, `as_of_date` = excluded.`as_of_date`, `source_ids` = excluded.`source_ids`, `content_version` = excluded.`content_version`;
INSERT INTO `company_business_lines` (`id`, `company_ticker`, `name`, `description`, `revenue_role`, `end_markets`, `display_order`) VALUES ('CEG_CLEAN_GENERATION', 'CEG', '청정 기저 발전', '원자력 중심의 대규모 무탄소 발전과 수력·풍력·태양광 자산을 운영합니다.', '낮은 변동비의 발전량과 청정에너지 속성을 판매합니다.', '미국 도매 전력시장, 유틸리티, 대형 전력 수요처', 0) ON CONFLICT (`id`) DO UPDATE SET `company_ticker` = excluded.`company_ticker`, `name` = excluded.`name`, `description` = excluded.`description`, `revenue_role` = excluded.`revenue_role`, `end_markets` = excluded.`end_markets`, `display_order` = excluded.`display_order`;
INSERT INTO `company_business_lines` (`id`, `company_ticker`, `name`, `description`, `revenue_role`, `end_markets`, `display_order`) VALUES ('CEG_DISPATCHABLE_GENERATION', 'CEG', '조정 가능 발전', 'Calpine 합병으로 가스발전·지열·배터리 자산이 추가돼 피크와 계통 신뢰도 수요에 대응합니다.', '전력·용량·보조서비스 가격과 가스 스프레드에서 수익을 얻습니다.', '텍사스, 캘리포니아, 미국 북동부 전력시장', 1) ON CONFLICT (`id`) DO UPDATE SET `company_ticker` = excluded.`company_ticker`, `name` = excluded.`name`, `description` = excluded.`description`, `revenue_role` = excluded.`revenue_role`, `end_markets` = excluded.`end_markets`, `display_order` = excluded.`display_order`;
INSERT INTO `company_business_lines` (`id`, `company_ticker`, `name`, `description`, `revenue_role`, `end_markets`, `display_order`) VALUES ('CEG_CUSTOMER_SOLUTIONS', 'CEG', '고객 공급·에너지 솔루션', '기업·공공·가정 고객에게 전력·가스와 지속가능성 솔루션을 제공합니다.', '소매 공급 마진과 장기 고객계약을 통해 발전 포트폴리오의 판매 채널을 확보합니다.', '상업·산업, 공공부문, 주거 고객', 2) ON CONFLICT (`id`) DO UPDATE SET `company_ticker` = excluded.`company_ticker`, `name` = excluded.`name`, `description` = excluded.`description`, `revenue_role` = excluded.`revenue_role`, `end_markets` = excluded.`end_markets`, `display_order` = excluded.`display_order`;
INSERT INTO `company_business_lines` (`id`, `company_ticker`, `name`, `description`, `revenue_role`, `end_markets`, `display_order`) VALUES ('COHR_DATACENTER_COMMUNICATIONS', 'COHR', 'Datacenter & Communications', 'AI 데이터센터와 통신망에 트랜시버·광부품·모듈·서브시스템을 공급합니다.', '고속 광링크 채택과 대역폭 증가가 매출 성장과 믹스 개선을 이끕니다.', 'AI 데이터센터, 클라우드, 통신장비', 0) ON CONFLICT (`id`) DO UPDATE SET `company_ticker` = excluded.`company_ticker`, `name` = excluded.`name`, `description` = excluded.`description`, `revenue_role` = excluded.`revenue_role`, `end_markets` = excluded.`end_markets`, `display_order` = excluded.`display_order`;
INSERT INTO `company_business_lines` (`id`, `company_ticker`, `name`, `description`, `revenue_role`, `end_markets`, `display_order`) VALUES ('COHR_INDUSTRIAL', 'COHR', 'Industrial', '레이저·광학계·엔지니어드 소재를 반도체 장비, 정밀가공과 계측 분야에 공급합니다.', '다양한 산업 응용에서 장비 채택과 교체·증설 수요를 매출로 전환합니다.', '반도체·디스플레이 장비, 정밀 제조, 생명과학·과학계측', 1) ON CONFLICT (`id`) DO UPDATE SET `company_ticker` = excluded.`company_ticker`, `name` = excluded.`name`, `description` = excluded.`description`, `revenue_role` = excluded.`revenue_role`, `end_markets` = excluded.`end_markets`, `display_order` = excluded.`display_order`;
